  function spawn(scene, tuple, encounter) { const [x,y,type,required]=tuple, radius=type==="sentinel"?34:25, base=type==="sentinel"?{maxHp:SENTINEL.hp,damage:SENTINEL.damage,recoveryMs:SENTINEL.recovery}:type==="shooter"?{maxHp:SHOOTER.hp,damage:SHOOTER.damage,cooldownMs:SHOOTER.cooldown}:{maxHp:TUNE.enemyMaxHp,damage:TUNE.enemyDamage,cooldownMs:TUNE.enemyAttackCooldownMs}, tuned=global.AlphaSectorCombatConfig?.scaleEnemyCombat?.(base,scene.ahRun?.threatSnapshot)||base, scale=type==="sentinel"?.42:.30; const e=scene.textures.exists(PRODUCTION_PRESENTATION.chaser.key)?scene.physics.add.sprite(x,y,PRODUCTION_PRESENTATION.chaser.key,0).setScale(scale).setDepth(25):scene.add.rectangle(x,y,radius*2,radius*2,type==="shooter"?0xe0a24d:0xb44973,.95).setDepth(25); if(type==="shooter")e.setTint?.(0xf0b35b);else if(type==="sentinel")e.setTint?.(0xffd27d);else e.setTint?.(0xe88fae); addMobileBody(scene,e,radius);addActorShadow(scene,e,radius*2,24);animateActor(e,"rf02-chaser",-1,0,false); e.ah={type,required:!!required,encounter:encounter.id,hp:tuned.maxHp,maxHp:tuned.maxHp,damage:tuned.damage,cooldownMs:tuned.cooldownMs,recoveryMs:tuned.recoveryMs,next:0,state:"idle",until:0,dead:false,hitThisLunge:false,howlKnockbackImmune:type==="sentinel"}; e.ahCombat=e.ah; scene.ahEnemies.add(e); }
