  function showCombatNumber(scene,x,y,label,color,fontSize="12px",duration=400) { const number=trackCombatFx(scene,scene.add.text(x+(Math.random()-.5)*16,y-28,label,{fontFamily:"system-ui",fontSize,color,fontStyle:"bold",stroke:"#081018",strokeThickness:3}).setOrigin(.5).setDepth(55));scene.tweens.add({targets:number,y:number.y-24,alpha:0,duration,onComplete:()=>number.destroy()});return number; }
