  function impactBurst(scene,x,y,dx=0,dy=-1,count=3) { const vfx=PRODUCTION_PRESENTATION.combatVfx.sparks;if(!scene.textures.exists(vfx.key))return;const length=Math.hypot(dx,dy)||1,nx=dx/length,ny=dy/length;for(let i=0;i<count;i++){const spread=(Math.random()-.5)*.8,px=nx-ny*spread,py=ny+nx*spread,distance=12+Math.random()*13,spark=trackCombatFx(scene,scene.add.sprite(x,y,vfx.key,Math.floor(Math.random()*vfx.frames)).setScale(.19).setDepth(54).setRotation(Math.atan2(py,px)));scene.tweens.add({targets:spark,x:x+px*distance,y:y+py*distance,alpha:0,scaleX:.42,scaleY:.42,duration:110+Math.round(Math.random()*35),onComplete:()=>spark.destroy()});} }
  function enemyPresentationTint(enemy) { const a=enemy?.ah;if(a?.type==="shooter")return 0xf0b35b;if(a?.type==="sentinel")return a.state==="telegraph"||a.state==="lunge"?0xff8b9f:0xffd27d;return 0xe88fae; }
