  function showDeathBurst(scene,enemy) { return playAnimatedVfx(scene,PRODUCTION_PRESENTATION.combatVfx.enemyDeath,enemy.x,enemy.y,enemy.ah?.type==="sentinel"?.48:.38,53,0); }
