  function showRewardFeedback(scene,x,y,exp,type) { showCombatNumber(scene,x,y,`+${exp} XP`,0xbfefff,"11px",380);if(!scene.textures.exists(PRODUCTION_PRESENTATION.rewardBeam.key))return;const beam=trackCombatFx(scene,scene.add.image(x,y+10,PRODUCTION_PRESENTATION.rewardBeam.key).setDisplaySize(type==="sentinel"?34:24,type==="sentinel"?68:48).setDepth(27).setAlpha(type==="sentinel"?.92:.72));scene.tweens.add({targets:beam,y:beam.y-14,alpha:0,duration:type==="sentinel"?320:280,onComplete:()=>beam.destroy()}); }
  function damageEnemy(scene,enemy,damage,source="melee") { if(!enemy?.active||enemy.ah?.dead)return false;const a=enemy.ah,previous=a.hp;a.hp=Math.max(0,a.hp-damage);const finalDamage=previous-a.hp;if(!finalDamage)return false;const p=scene.ahPlayer,dx=enemy.x-(p?.x||enemy.x),dy=enemy.y-(p?.y||enemy.y);flashEnemy(scene,enemy);showCombatNumber(scene,enemy.x,enemy.y,String(finalDamage),0xe8fdff);if(source==="melee"){showMeleeHit(scene,enemy,dx,dy);impactBurst(scene,enemy.x,enemy.y,dx,dy,3);}else if(source==="howl")impactBurst(scene,enemy.x,enemy.y,dx,dy,1);if(source==="melee")scene.cameras.main?.shake?.(a.type==="sentinel"?60:50,a.type==="sentinel"?.0024:.0017);if(a.hp<=0)kill(scene,enemy);return true; }
  function hurt(scene,amount,source=amount===SHOOTER.damage?"projectile":"hostile") { const r=scene.ahRun;if(!r||r.status!=="active")return;const finalDamage=global.AlphaSectorCombatConfig?.incomingPlayerDamage?.(amount,r.combatSnapshot);if(!finalDamage)return;const runId=r.runId,p=scene.ahPlayer;r.playerHP=Math.max(0,r.playerHP-finalDamage);r.damageTaken+=finalDamage;if(p?.setTint){p.setTint(0xff7896);scene.time.delayedCall(90,()=>{if(scene.ahRun?.runId===runId)scene.ahPlayer?.clearTint?.();});}else{p?.setFillStyle?.(0xff7896);scene.time.delayedCall(90,()=>{if(scene.ahRun?.runId===runId)scene.ahPlayer?.setFillStyle?.(0x85dff4);});}if(source==="projectile")showProjectileImpact(scene,p.x,p.y);showCombatNumber(scene,p.x,p.y,`-${finalDamage}`,0xff9aac,"12px",400);impactBurst(scene,p.x,p.y,0,-1,source==="projectile"?2:2);scene.cameras.main?.shake?.(70,.0026);if(!r.playerHP)fail(scene);hud(scene); }
  function kill(scene,e) { if(!e?.active||e.ah.dead)return;const r=scene.ahRun,a=e.ah,expBefore=r.expEarned;a.dead=true;e.body.enable=false;e.body.setVelocity?.(0,0);global.AlphaSectorCombatConfig.recordEnemyKill(r,a.type,a.required);r.expEarned+=12;r.bonesEarned+=a.type==="sentinel"?3:1;r.scrapEarned+=a.type==="sentinel"?3:1;const expDelta=r.expEarned-expBefore,state=r.encounters[a.encounter];state.remaining=Math.max(0,state.remaining-1);e.setTint?.(0xffffff);showDeathBurst(scene,e);impactBurst(scene,e.x,e.y,0,-1,3);showRewardFeedback(scene,e.x,e.y,expDelta,a.type);const duration=a.type==="sentinel"?280:180;scene.tweens.add({targets:e,alpha:0,scaleX:e.scaleX*.58,scaleY:e.scaleY*.58,duration,onComplete:()=>{destroyActorShadow(e);e.destroy();}});if(e.ahShadow||e.ahShadowContact)scene.tweens.add({targets:[e.ahShadow,e.ahShadowContact].filter(Boolean),alpha:0,scaleX:.72,scaleY:.72,duration,onComplete:()=>destroyActorShadow(e)});if(a.type==="sentinel")scene.cameras.main?.shake?.(90,.0028);if(!state.remaining)clear(scene,a.encounter);hud(scene); }
  function attack(scene) { const r=scene.ahRun;if(!r||r.status!=="active"||scene.time.now<(scene.ahAttackAt||0))return;let target=null,best=Infinity;enemyChildren(scene).forEach(e=>{if(e.active&&!e.ah.dead){const d=Phaser.Math.Distance.Between(scene.ahPlayer.x,scene.ahPlayer.y,e.x,e.y);if(d<best){best=d;target=e;}}});if(!target||best>TUNE.playerAttackRange)return;if(target.ah.type==="sentinel"&&target.ah.state!=="recovery"){showSlash(scene,target);showSentinelBlock(scene,target);text(scene,"SENTINEL ARMOUR LOCKED");return;}scene.ahAttackAt=scene.time.now+TUNE.playerAttackCooldownMs;showSlash(scene,target);damageEnemy(scene,target,r.combatSnapshot.meleeDamage,"melee"); }
