  function fire(scene,e,nx,ny){const b=scene.add.circle(e.x,e.y,7,0xffc46b,1).setDepth(28);scene.physics.add.existing(b);b.body.setCircle(7);b.body.setAllowGravity(false);b.body.setVelocity(nx*SHOOTER.projectileSpeed,ny*SHOOTER.projectileSpeed);b.ahDamage=e.ah.damage;b.ahEnd=scene.time.now+3600;scene.ahProjectiles.add(b);}
  function enemyUpdate(scene,e,time){const p=scene.ahPlayer,a=e.ah,dx=p.x-e.x,dy=p.y-e.y,d=Math.hypot(dx,dy)||1;if(a.type==="sentinel"){if(a.state==="idle"){e.body.setVelocity(dx/d*SENTINEL.speed,dy/d*SENTINEL.speed);if(time>=a.until){a.state="telegraph";a.until=time+SENTINEL.telegraph;e.setTint?.(0xff8b9f);}}else if(a.state==="telegraph"&&time>=a.until){a.state="lunge";a.until=time+SENTINEL.lunge;a.vx=dx/d;a.vy=dy/d;a.hitThisLunge=false;e.body.setVelocity(a.vx*SENTINEL.lungeSpeed,a.vy*SENTINEL.lungeSpeed);}else if(a.state==="lunge"&&time>=a.until){e.body.setVelocity(0,0);a.state="recovery";a.until=time+a.recoveryMs;e.setTint?.(0xffd27d);}else if(a.state==="recovery"&&time>=a.until){a.state="idle";a.until=time+350;}if(a.state==="lunge"&&d<68&&!a.hitThisLunge){a.hitThisLunge=true;hurt(scene,a.damage);}animateActor(e,"rf02-chaser",e.body.velocity.x,e.body.velocity.y,e.body.velocity.lengthSq()>1);syncActorShadow(e);return;}if(a.type==="shooter"){if(d<SHOOTER.aggro){const speed=d<130?-SHOOTER.speed:d>SHOOTER.preferred?SHOOTER.speed:0;e.body.setVelocity(dx/d*speed,dy/d*speed);if(time>=a.next){a.next=time+a.cooldownMs;fire(scene,e,dx/d,dy/d);}}animateActor(e,"rf02-chaser",e.body.velocity.x,e.body.velocity.y,e.body.velocity.lengthSq()>1);syncActorShadow(e);return;}if(d<TUNE.enemyAggroRange){e.body.setVelocity(dx/d*TUNE.enemySpeed,dy/d*TUNE.enemySpeed);if(d<TUNE.enemyAttackRange&&time>=a.next){a.next=time+a.cooldownMs;hurt(scene,a.damage);}}else e.body.setVelocity(0,0);animateActor(e,"rf02-chaser",e.body.velocity.x,e.body.velocity.y,e.body.velocity.lengthSq()>1);syncActorShadow(e);}
  function surge(scene,time){const r=scene.ahRun;if(!r||r.status!=="active")return;const s=scene.ahSurge,inLaneArea=scene.ahPlayer.x>=2700&&scene.ahPlayer.x<=3850;if(s.phase==="idle"&&!inLaneArea)return;if(time<s.nextAt)return;const [x,y,w,h]=LANE_RECTS[s.index],fx=scene.ahSurgeGraphics;if(s.phase==="idle"){s.phase="telegraph";s.nextAt=time+900;s.hit=false;fx.clear().fillStyle(0xdca54a,.29).fillRect(x,y,w,h).lineStyle(5,0xf1c56c,.94).strokeRect(x+3,y+3,w-6,h-6);text(scene,"SIGNAL SURGE INCOMING");}else if(s.phase==="telegraph"){s.phase="active";s.nextAt=time+250;fx.clear().fillStyle(0xbffaff,.84).fillRect(x,y,w,h).lineStyle(6,0xffffff,.98).strokeRect(x+3,y+3,w-6,h-6);if(scene.ahPlayer.x>x&&scene.ahPlayer.x<x+w&&scene.ahPlayer.y>y&&scene.ahPlayer.y<y+h){s.hit=true;r.hazardHits++;hurt(scene,8);}}else{s.phase="idle";s.index=(s.index+1)%LANE_RECTS.length;s.nextAt=time+2600;fx.clear();}}
  function cache(scene){const r=scene.ahRun;if(r.cacheOpened||!r.encounters.maintenance_cache.cleared)return;r.cacheOpened=true;const restore=Math.min(Math.max(0,r.combatSnapshot.maxHp-r.playerHP),Math.max(12,Math.round(r.combatSnapshot.maxHp*.25)));r.playerHP+=restore;r.cacheHealing=restore;text(scene,restore?`CACHE FIELD REPAIR // +${restore} HP`:"CACHE FIELD REPAIR // SYSTEMS NOMINAL");hud(scene);}
  function updateContext(scene){const r=scene.ahRun,p=scene.ahPlayer;if(!r||!p?.active||!scene.ahTouch)return;let label="";if(r.status==="cleared"&&Phaser.Math.Distance.Between(p.x,p.y,scene.ahRelay.x,scene.ahRelay.y)<120)label="ACTIVATE";else if(!r.cacheOpened&&r.encounters.maintenance_cache.cleared&&Phaser.Math.Distance.Between(p.x,p.y,scene.ahCache.x,scene.ahCache.y)<105)label="FIELD\nREPAIR";scene.ahInteractLabel?.setText(label||"ACTIVATE");[scene.ahInteractRing,scene.ahInteractIcon,scene.ahInteractLabel,scene.ahInteractHit].forEach(item=>item?.setVisible(!!label));if(scene.ahInteractHit?.input)scene.ahInteractHit.input.enabled=!!label;}
